function binaryStrings(n) {
  const result = [];
  const path = [];                         // the choices made so far
  const build = () => {
    if (path.length === n) {               // a full string: record it
      result.push(path.join(""));
      return;
    }
    for (const bit of ["0", "1"]) {
      path.push(bit);                      // choose
      build();                             // explore
      path.pop();                          // un-choose
    }
  };
  build();
  return result;
}

List<String> binaryStrings(int n) {
    List<String> result = new ArrayList<>();
    build(n, new StringBuilder(), result);
    return result;
}

void build(int n, StringBuilder path, List<String> result) {
    if (path.length() == n) {             // a full string: record it
        result.add(path.toString());
        return;
    }
    for (char bit : new char[]{'0', '1'}) {
        path.append(bit);                 // choose
        build(n, path, result);           // explore
        path.deleteCharAt(path.length() - 1);   // un-choose
    }
}

void build(int n, string& path, vector<string>& result) {
    if ((int)path.size() == n) {          // a full string: record it
        result.push_back(path);
        return;
    }
    for (char bit : {'0', '1'}) {
        path.push_back(bit);              // choose
        build(n, path, result);           // explore
        path.pop_back();                  // un-choose
    }
}

vector<string> binaryStrings(int n) {
    vector<string> result;
    string path;
    build(n, path, result);
    return result;
}
